using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

public class ActionDescriptionInstancePositioner : MonoBehaviour
{
	[Header("Components")]
	[SerializeField]
	private ActionDescriptionInstance actionDescriptionInstance;

	[SerializeField]
	private GameObject actionDescriptionInstanceExtraTags;

	[SerializeField]
	private ActionDescriptionPanel actionDescriptionPanel;

	[SerializeField]
	private Transform topAnchorPoint;

	[SerializeField]
	private Transform bottomAnchorPoint;

	[SerializeField]
	private Transform rightAnchorPoint;

	[SerializeField]
	private Transform leftAnchorPoint;

	[SerializeField]
	private float padding;

	[SerializeField]
	private float actionDescriptionInstanceMargin;

	[Header("Reference")]
	[SerializeField]
	private CanvasReference tooltipCanvas;

	private RectTransform actionDescriptionInstanceRect;

	private PositionOverride[] positionOverrides = new PositionOverride[0];

	private void Awake()
	{
		actionDescriptionInstanceRect = actionDescriptionInstance.GetComponent<RectTransform>();
	}

	public void SetAlignment(bool upAlignment, bool centerAlignment = false)
	{
		if (centerAlignment)
		{
			actionDescriptionInstanceRect.pivot = new Vector2(0.5f, 0.5f);
		}
		else if (upAlignment)
		{
			actionDescriptionInstanceRect.pivot = new Vector2(0.5f, 0f);
		}
		else
		{
			actionDescriptionInstanceRect.pivot = new Vector2(0.5f, 1f);
		}
	}

	public void AdjustAnchor(bool downAlignmentWithoutVerticalPadding)
	{
		actionDescriptionInstance.transform.position = topAnchorPoint.position;
		bool num = actionDescriptionInstanceRect.pivot == new Vector2(0.5f, 0f);
		actionDescriptionPanel.SetActionDescriptionInstanceExtraTagsLeftOrRightPosition(right: true);
		if (num)
		{
			if (GetScreenAdjustedSize().y - (GetActionDescriptionInstanceYPositionWithoutBlackBars() + GetTooltipHeightWithMarginAndPadding()) < 0f)
			{
				TooltipNotVisibleOnTopTryBottom();
			}
			else
			{
				CheckSidesPadding();
			}
		}
		else if (downAlignmentWithoutVerticalPadding)
		{
			CheckSidesPadding();
		}
		else
		{
			CheckVerticalPaddingDownAlignment();
			CheckSidesPadding();
		}
	}

	private Vector2 GetScreenAdjustedSize()
	{
		return new Vector2(Screen.width, Screen.height);
	}

	private float GetActionDescriptionInstanceYPositionWithoutBlackBars()
	{
		return actionDescriptionInstance.transform.position.y;
	}

	private float GetActionDescriptionInstanceXPositionWithoutBlackBars()
	{
		return actionDescriptionInstance.transform.position.x;
	}

	private float GetTransformYPositionWithoutBlackBars(Vector3 position)
	{
		return position.y;
	}

	private float GetTransformXPositionWithoutBlackBars(Vector3 position)
	{
		return position.x;
	}

	private void CheckVerticalPaddingDownAlignment()
	{
		float num = (actionDescriptionInstanceRect.rect.height - actionDescriptionInstanceMargin + padding) * tooltipCanvas.Value.scaleFactor;
		float num2 = GetActionDescriptionInstanceYPositionWithoutBlackBars() - num;
		if (num2 < 0f)
		{
			Vector3 position = actionDescriptionInstance.transform.position;
			position.y -= num2;
			actionDescriptionInstance.transform.position = position;
			actionDescriptionPanel.SetActionDescriptionInstanceExtraTagsLeftOrRightPosition(right: true);
		}
	}

	private void CheckSidesPadding()
	{
		float num = actionDescriptionInstanceRect.rect.width / 2f + padding - actionDescriptionInstanceMargin;
		float halfTooltipWidthWithMarginAndPadding = num * tooltipCanvas.Value.scaleFactor;
		if (GetRightEdgeToScreenEdgeDistance() < 0f)
		{
			Vector3 position = actionDescriptionInstance.transform.position;
			position.x += GetRightEdgeToScreenEdgeDistance();
			actionDescriptionInstance.transform.position = position;
			actionDescriptionPanel.SetActionDescriptionInstanceExtraTagsLeftOrRightPosition(right: false);
		}
		else if (GetLeftEdgeToScreenEdgeDistance() < 0f)
		{
			Vector3 position2 = actionDescriptionInstance.transform.position;
			position2.x -= GetLeftEdgeToScreenEdgeDistance();
			actionDescriptionInstance.transform.position = position2;
			actionDescriptionPanel.SetActionDescriptionInstanceExtraTagsLeftOrRightPosition(right: true);
		}
		if (GetActionDescriptionInstanceExtraTagsExtraWidth() > 0f)
		{
			num += GetActionDescriptionInstanceExtraTagsExtraWidth();
			halfTooltipWidthWithMarginAndPadding = num * tooltipCanvas.Value.scaleFactor;
			if (GetRightEdgeToScreenEdgeDistance() < 0f)
			{
				actionDescriptionPanel.SetActionDescriptionInstanceExtraTagsLeftOrRightPosition(right: false);
			}
			else if (GetLeftEdgeToScreenEdgeDistance() < 0f)
			{
				actionDescriptionPanel.SetActionDescriptionInstanceExtraTagsLeftOrRightPosition(right: true);
			}
		}
		float GetLeftEdgeToScreenEdgeDistance()
		{
			return GetActionDescriptionInstanceXPositionWithoutBlackBars() - halfTooltipWidthWithMarginAndPadding;
		}
		float GetRightEdgeToScreenEdgeDistance()
		{
			return GetScreenAdjustedSize().x - (GetActionDescriptionInstanceXPositionWithoutBlackBars() + halfTooltipWidthWithMarginAndPadding);
		}
	}

	private float GetActionDescriptionInstanceExtraTagsExtraWidth()
	{
		if (!actionDescriptionInstanceExtraTags.activeInHierarchy)
		{
			return 0f;
		}
		return actionDescriptionPanel.ActionDescriptionInstanceExtraTagsXPosition;
	}

	private void TooltipNotVisibleOnTopTryBottom()
	{
		Vector3 position = GetPositionOverride(PositionOverrideType.BOTTOM)?.positionOverridePosition ?? bottomAnchorPoint.position;
		if (GetTransformYPositionWithoutBlackBars(position) - GetTooltipHeightWithMarginAndPadding() < 0f)
		{
			TryChangeToRightOrLeftAnchor();
			CheckVerticalPadding();
			return;
		}
		actionDescriptionInstance.transform.position = position;
		actionDescriptionPanel.SetActionDescriptionInstanceExtraTagsLeftOrRightPosition(right: true);
		actionDescriptionInstanceRect.pivot = new Vector2(0.5f, 1f);
		CheckSidesPadding();
	}

	private void CheckVerticalPadding()
	{
		float num = (actionDescriptionInstanceRect.rect.height / 2f - actionDescriptionInstanceMargin + padding) * tooltipCanvas.Value.scaleFactor;
		float num2 = GetScreenAdjustedSize().y - (GetActionDescriptionInstanceYPositionWithoutBlackBars() + num);
		if (num2 < 0f)
		{
			Vector3 position = actionDescriptionInstance.transform.position;
			position.y += num2;
			actionDescriptionInstance.transform.position = position;
			return;
		}
		float num3 = GetActionDescriptionInstanceYPositionWithoutBlackBars() - num;
		if (num3 < 0f)
		{
			Vector3 position2 = actionDescriptionInstance.transform.position;
			position2.y -= num3;
			actionDescriptionInstance.transform.position = position2;
		}
	}

	private void TryChangeToRightOrLeftAnchor()
	{
		Vector3 position = GetPositionOverride(PositionOverrideType.RIGHT)?.positionOverridePosition ?? rightAnchorPoint.position;
		if (GetScreenAdjustedSize().x - (GetTransformXPositionWithoutBlackBars(position) + padding - actionDescriptionInstanceMargin + (actionDescriptionInstanceRect.rect.width / 2f + GetActionDescriptionInstanceExtraTagsExtraWidth()) * tooltipCanvas.Value.scaleFactor) < 0f)
		{
			Vector3 position2 = GetPositionOverride(PositionOverrideType.LEFT)?.positionOverridePosition ?? leftAnchorPoint.position;
			actionDescriptionInstance.transform.position = position2;
			actionDescriptionPanel.SetActionDescriptionInstanceExtraTagsLeftOrRightPosition(right: false);
		}
		else
		{
			actionDescriptionInstance.transform.position = position;
			actionDescriptionPanel.SetActionDescriptionInstanceExtraTagsLeftOrRightPosition(right: true);
		}
		actionDescriptionInstanceRect.pivot = new Vector2(0.5f, 0.5f);
	}

	private float GetTooltipHeightWithMarginAndPadding()
	{
		return (actionDescriptionInstanceRect.rect.height - actionDescriptionInstanceMargin + padding) * tooltipCanvas.Value.scaleFactor;
	}

	public void OverridePositions(PositionOverride[] positionOverrides)
	{
		this.positionOverrides = positionOverrides;
	}

	public void ResetOverridePositions()
	{
		positionOverrides = new PositionOverride[0];
	}

	private PositionOverride GetPositionOverride(PositionOverrideType positionOverrideType)
	{
		for (int i = 0; i < positionOverrides.Length; i++)
		{
			if (positionOverrides[i].positionOverrideType == positionOverrideType)
			{
				return positionOverrides[i];
			}
		}
		return null;
	}
}
